class RaceEvidenceTests(unittest.TestCase):
    def assess(self, raw, mode, fixture, **kw):
        return assess_cycles(raw, 2, [fixture], mode=mode, identity=kw.pop('identity', IDENTITY), **kw)
    def reject(self, raw, mode, fixture, **kw):
        self.assertEqual(self.assess(raw, mode, fixture, **kw)['status'], 'FAIL')
    def test_parser_controls_for_both_orders(self):
        for mode, fixture, raw in CONTROLS:
            r = self.assess(raw, mode, fixture)
            self.assertEqual(r['status'], 'PASS', r['errors'])
            self.assertEqual(r['concurrent_invocation_overlap'], 'OBSERVED')
    def test_every_actual_race_event_is_required(self):
        for mode, fixture, raw in CONTROLS:
            lines = raw.splitlines()
            for i, line in enumerate(lines):
                if line.startswith(('[RC-RACE]', '[RC-OUTCOME]')):
                    with self.subTest(mode=mode, line=line):
                        self.reject('\n'.join(lines[:i]+lines[i+1:]), mode, fixture)
    def test_same_cpu_and_sequential_arrival_rejected(self):
        for mode, fixture, raw in CONTROLS:
            line = next(l for l in raw.splitlines() if l.startswith('[RC-RACE]') and 'event=entered actor=2 ' in l)
            self.reject(raw.replace(line, line.replace('cpu=0', 'cpu=1')), mode, fixture)
            self.reject(raw.replace(line, re.sub(r'seq=\d+', 'seq=999', line)), mode, fixture)
    def test_identity_generation_and_endpoint_mismatches_rejected(self):
        for mode, fixture, raw in CONTROLS:
            line = next(l for l in raw.splitlines() if l.startswith('[RC-RACE]') and 'event=entered actor=1 ' in l)
            for key in ('pid','inc','caller','caller_inc','endpoint','generation'):
                self.reject(raw.replace(line, re.sub(key+r'=\d+\b', key+'=999', line)), mode, fixture)
    def test_duplicate_terminal_retirement_free_and_race_rejected(self):
        for mode, fixture, raw in CONTROLS:
            for prefix in ('[AE-TERMINAL]', '[AE-PMM]', '[RC-RACE]', '[RC-OUTCOME]'):
                line = next(l for l in raw.splitlines() if l.startswith(prefix))
                self.reject(raw+'\n'+line, mode, fixture)
            line = next(l for l in raw.splitlines() if l.startswith('[AE-GRANT]') and 'event=retired ' in l)
            self.reject(raw+'\n'+line, mode, fixture)
    def test_loser_result_and_outcome_preservation_required(self):
        for mode, fixture, raw in CONTROLS:
            line = next(l for l in raw.splitlines() if l.startswith('[RC-RACE]') and 'event=returned actor=1 ' in l)
            self.reject(raw.replace(line, re.sub(r'result=\d+', 'result=99', line)), mode, fixture)
            self.reject(raw.replace('pending=0 reply=', 'pending=1 reply='), mode, fixture)
            line = next(l for l in raw.splitlines() if l.startswith('[CE-STATE]') and 'event=race-late-cancel-after ' in l)
            self.reject(raw.replace(line, line.replace('outcome=Some(', 'outcome=Changed(')), mode, fixture)
    def test_independent_acknowledgements_and_late_denials_required(self):
        for mode, fixture, raw in CONTROLS:
            for event in ('caller-result-matched', 'late-completions-rejected', 'race-late-cancel-before', 'race-late-cancel-after'):
                self.reject('\n'.join(l for l in raw.splitlines() if 'event='+event+' ' not in l), mode, fixture)
    def test_physical_unmap_remote_ack_and_inventories_required(self):
        for mode, fixture, raw in CONTROLS:
            for prefix in ('[AE-UNMAP]', '[AE-TLB]', '[AE-PMM]', '[CE-REAP]'):
                self.reject('\n'.join(l for l in raw.splitlines() if not l.startswith(prefix)), mode, fixture)
            line = next(l for l in raw.splitlines() if l.startswith('[AE-TLB]') and 'event=ack-observed ' in l)
            self.reject(raw.replace(line, re.sub(r'produced=\d+', 'produced=999', line)), mode, fixture)
            self.reject(raw.replace('receipts=0', 'receipts=1'), mode, fixture)
    def test_timeout_and_identity_fail_closed(self):
        for mode, fixture, raw in CONTROLS:
            self.reject(raw, mode, fixture, failure={'type':'TimeoutError'})
            self.reject(raw, mode, fixture, identity=None)
            self.reject(raw+'\nPANIC', mode, fixture)

if __name__ == '__main__': unittest.main()
